/**
 * Persistent Client-Side Podcast Audio Store (IndexedDB + In-Memory ObjectURL Cache)
 *
 * Stores studio-mastered 2-channel Stereo WAV audio blobs generated by `neuralTtsWorker.js`
 * so custom on-demand podcasts survive page reloads, tab switches, and offline playback
 * on iPhone Safari, Home Screen PWAs, Android Chrome, and desktop browsers.
 */

const DB_NAME = '49ers_faithful_podcast_audio_v1';
const STORE_NAME = 'episode_wavs';
const DB_VERSION = 1;
const MAX_STORED_EPISODES = 16;

const memoryBlobFallback = new Map();
const objectUrlCache = new Map();
let dbPromise = null;

function openAudioDb() {
  if (typeof indexedDB === 'undefined') return Promise.resolve(null);
  if (dbPromise) return dbPromise;

  dbPromise = new Promise(resolve => {
    try {
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'episodeId' });
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    } catch {
      resolve(null);
    }
  });

  return dbPromise;
}

/**
 * Persists a synthesized Stereo WAV Blob/ArrayBuffer for an episode and returns
 * a playable `blob:` Object URL for HTML5 `<audio>`.
 */
export async function saveEpisodeAudioBlob(episodeId, wavBlobOrBuffer) {
  if (!episodeId || !wavBlobOrBuffer) return null;
  const id = String(episodeId);
  const blob =
    wavBlobOrBuffer instanceof Blob
      ? wavBlobOrBuffer
      : new Blob([wavBlobOrBuffer], { type: 'audio/wav' });

  const prevUrl = objectUrlCache.get(id);
  if (prevUrl && typeof URL !== 'undefined' && typeof URL.revokeObjectURL === 'function') {
    try {
      URL.revokeObjectURL(prevUrl);
    } catch {}
  }

  let objectUrl = null;
  if (typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function') {
    objectUrl = URL.createObjectURL(blob);
    objectUrlCache.set(id, objectUrl);
  }
  memoryBlobFallback.set(id, blob);

  const db = await openAudioDb();
  if (db) {
    try {
      const arrBuf = await blob.arrayBuffer();
      await new Promise(resolve => {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        store.put({
          episodeId: id,
          mimeType: blob.type || 'audio/wav',
          savedAt: Date.now(),
          buffer: arrBuf
        });
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => resolve(false);
      });
      pruneOldStoredEpisodes(db).catch(() => {});
    } catch {
      // Keep serving from memoryBlobFallback / objectUrlCache if quota is full
    }
  }

  return objectUrl;
}

async function pruneOldStoredEpisodes(db) {
  return new Promise(resolve => {
    try {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      const getAllReq = store.getAll();
      getAllReq.onsuccess = () => {
        const rows = Array.isArray(getAllReq.result) ? getAllReq.result : [];
        if (rows.length > MAX_STORED_EPISODES) {
          rows
            .sort((a, b) => Number(b.savedAt || 0) - Number(a.savedAt || 0))
            .slice(MAX_STORED_EPISODES)
            .forEach(oldRow => {
              if (oldRow?.episodeId) store.delete(oldRow.episodeId);
            });
        }
      };
      tx.oncomplete = () => resolve();
      tx.onerror = () => resolve();
    } catch {
      resolve();
    }
  });
}

/**
 * Synchronously returns an already-hydrated `blob:` URL from the in-memory cache if available,
 * allowing `<audio>.play()` to execute synchronously inside an iOS Safari tap gesture.
 */
export function peekCachedEpisodeAudioUrl(episodeId) {
  if (!episodeId) return null;
  return objectUrlCache.get(String(episodeId)) || null;
}

/**
 * Resolves a playable `blob:` URL for a locally synthesized episode, hydrating from
 * IndexedDB if the page was reloaded since synthesis.
 */
export async function getEpisodeAudioUrl(episodeId) {
  if (!episodeId) return null;
  const id = String(episodeId);

  if (objectUrlCache.has(id)) {
    return objectUrlCache.get(id);
  }

  if (memoryBlobFallback.has(id)) {
    const memBlob = memoryBlobFallback.get(id);
    if (typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function') {
      const url = URL.createObjectURL(memBlob);
      objectUrlCache.set(id, url);
      return url;
    }
  }

  const db = await openAudioDb();
  if (!db) return null;

  try {
    const record = await new Promise(resolve => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });

    if (record?.buffer) {
      const blob = new Blob([record.buffer], { type: record.mimeType || 'audio/wav' });
      memoryBlobFallback.set(id, blob);
      if (typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function') {
        const url = URL.createObjectURL(blob);
        objectUrlCache.set(id, url);
        return url;
      }
    }
  } catch {}

  return null;
}

/**
 * Synchronously returns true if a synthesized studio audio blob is currently loaded in memory.
 */
export function hasCachedEpisodeAudioSync(episodeId) {
  if (!episodeId) return false;
  const id = String(episodeId);
  return objectUrlCache.has(id) || memoryBlobFallback.has(id);
}

/**
 * Retrieves the raw stored Blob for a locally synthesized episode (from memory or IndexedDB).
 */
export async function getEpisodeAudioBlob(episodeId) {
  if (!episodeId) return null;
  const id = String(episodeId);
  if (memoryBlobFallback.has(id)) {
    return memoryBlobFallback.get(id);
  }
  await getEpisodeAudioUrl(id);
  return memoryBlobFallback.get(id) || null;
}

let lameLoaderPromise = null;

function ensureLameMp3Encoder() {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return Promise.resolve(null);
  }
  if (window.lamejs?.Mp3Encoder) {
    return Promise.resolve(window.lamejs);
  }
  if (lameLoaderPromise) return lameLoaderPromise;

  lameLoaderPromise = new Promise(resolve => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/lamejs@1.2.1/lame.min.js';
    script.async = true;
    const timer = setTimeout(() => resolve(null), 3500);
    script.onload = () => {
      clearTimeout(timer);
      resolve(window.lamejs?.Mp3Encoder ? window.lamejs : null);
    };
    script.onerror = () => {
      clearTimeout(timer);
      lameLoaderPromise = null;
      resolve(null);
    };
    document.head.appendChild(script);
  });

  return lameLoaderPromise;
}

/**
 * Exports a compact ~600–800 KB 48 kbps `.mp3` `File` (18x smaller than raw 12.5 MB WAV)
 * for instant native iMessage / WhatsApp / AirDrop audio sharing or download.
 */
export async function exportEpisodeShareableAudioFile(episode, kbps = 48) {
  if (!episode?.id) return null;
  const rawBlob = await getEpisodeAudioBlob(episode.id);
  if (!rawBlob) return null;

  const safeSlug = String(episode.title || '49ers-podcast')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 48) || '49ers-podcast';

  try {
    const arrBuf = await rawBlob.arrayBuffer();
    if (arrBuf.byteLength > 44) {
      const view = new DataView(arrBuf);
      const riff =
        String.fromCharCode(view.getUint8(0), view.getUint8(1), view.getUint8(2), view.getUint8(3)) ===
        'RIFF';
      const lame = riff ? await ensureLameMp3Encoder() : null;
      if (lame?.Mp3Encoder) {
        const numChannels = Math.max(1, view.getUint16(22, true));
        const sampleRate = Math.max(8000, view.getUint32(24, true));
        const bytesPerFrame = numChannels * 2;
        const numFrames = Math.floor((arrBuf.byteLength - 44) / bytesPerFrame);
        const monoSamples = new Int16Array(numFrames);
        let byteOff = 44;
        for (let i = 0; i < numFrames; i++) {
          monoSamples[i] = view.getInt16(byteOff, true);
          byteOff += bytesPerFrame;
        }

        const encoder = new lame.Mp3Encoder(1, sampleRate, kbps);
        const mp3Chunks = [];
        const blockSize = 1152 * 10;
        for (let i = 0; i < monoSamples.length; i += blockSize) {
          const buf = encoder.encodeBuffer(monoSamples.subarray(i, i + blockSize));
          if (buf.length > 0) mp3Chunks.push(new Uint8Array(buf));
        }
        const tail = encoder.flush();
        if (tail.length > 0) mp3Chunks.push(new Uint8Array(tail));

        if (typeof File === 'function') {
          return new File(mp3Chunks, `${safeSlug}.mp3`, { type: 'audio/mpeg' });
        }
        const mp3Blob = new Blob(mp3Chunks, { type: 'audio/mpeg' });
        mp3Blob.name = `${safeSlug}.mp3`;
        return mp3Blob;
      }
    }
  } catch {
    // Fall back cleanly to original WAV Blob below
  }

  if (typeof File === 'function') {
    return new File([rawBlob], `${safeSlug}.wav`, { type: rawBlob.type || 'audio/wav' });
  }
  return rawBlob;
}

/**
 * Permanently removes a synthesized podcast's cached audio Blob & Object URL
 * from memory and IndexedDB when the user deletes the episode.
 */
export async function deleteEpisodeAudioBlob(episodeId) {
  if (!episodeId) return false;
  const id = String(episodeId);

  const prevUrl = objectUrlCache.get(id);
  if (prevUrl && typeof URL !== 'undefined' && typeof URL.revokeObjectURL === 'function') {
    try {
      URL.revokeObjectURL(prevUrl);
    } catch {}
  }
  objectUrlCache.delete(id);
  memoryBlobFallback.delete(id);

  const db = await openAudioDb();
  if (!db) return true;

  try {
    await new Promise(resolve => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      store.delete(id);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    });
  } catch {}

  return true;
}
